aqui tienes el codigo para crear un arbol binario en javascript:

```javascript
class nodo {
    constructor(valor) {
        this.valor = valor;
        this.izquierda = null;
        this.derecha = null;
    }
}

class arbolbinario {
    constructor() {
        this.raiz = null;
    }

    insertar(valor) {
        let nuevonodo = new nodo(valor);
        if (this.raiz === null) {
            this.raiz = nuevonodo;
        } else {
            this.insertarnodo(this.raiz, nuevonodo);
        }
    }

    insertarnodo(nodo, nuevonodo) {
        if (nuevonodo.valor < nodo.valor) {
            if (nodo.izquierda === null) {
                nodo.izquierda = nuevonodo;
            } else {
                this.insertarnodo(nodo.izquierda, nuevonodo);
            }
        } else {
            if (nodo.derecha === null) {
                nodo.derecha = nuevonodo;
            } else {
                this.insertarnodo(nodo.derecha, nuevonodo);
            }
        }
    }
}

let arbol = new arbolbinario();
arbol.insertar(10);
arbol.insertar(5);
arbol.insertar(15);
arbol.insertar(3);
console.log(arbol);
```

aqui tienes el codigo para crear un arbol binario en python:

```python
class nodo:
    def __init__(self, valor):
        self.valor = valor
        self.izquierda = none
        self.derecha = none

class arbolbinario:
    def __init__(self):
        self.raiz = none

    def insertar(self, valor):
        nuevo_nodo = nodo(valor)
        if self.raiz is none:
            self.raiz = nuevo_nodo
        else:
            self.insertar_nodo(self.raiz, nuevo_nodo)

    def insertar_nodo(self, nodo, nuevo_nodo):
        if nuevo_nodo.valor < nodo.valor:
            if nodo.izquierda is none:
                nodo.izquierda = nuevo_nodo
            else:
                self.insertar_nodo(nodo.izquierda, nuevo_nodo)
        else:
            if nodo.derecha is none:
                nodo.derecha = nuevo_nodo
            else:
                self.insertar_nodo(nodo.derecha, nuevo_nodo)

arbol = arbolbinario()
arbol.insertar(10)
arbol.insertar(5)
arbol.insertar(15)
arbol.insertar(3)
print(arbol)
```

